mandate @ 0.6

module example.slots @ 0.1

use std.{fs, model}

type Note = { text: Text }

capability Docs     = fs.read("/work/docs")
capability ModelStd = model.infer(tier: standard, max_class: internal)

agent Writer {
  role   "Writes a note about what it reads."
  caps   Docs, ModelStd
  budget { tokens: 1k, spend: 0.01 USD, steps: 2 }
  skill write(topic: Text) -> Inferred<Note> ! {Fs.Read, Model}
}

/// A note on a topic, written by a skill that reads only what the read slot
/// hands it, narrowed to the topic's folder.
pattern One(page: type, author: skill(Text) -> Inferred<page>, read: capability) -> Inferred<page> {
  let made: Inferred<page> = delegate author("notes") with caps read.narrow("/work/docs/notes")
  made
}

workflow Draft = One(page: Note, author: Writer.write, read: Docs)
  caps   Docs, ModelStd
  budget { spend: 1 USD }
